<?php
declare(strict_types=1);require_once __DIR__.'/../src/page_security.php';$currentUser=lszj_require_page_login();$date=(string)($_GET['date']??date('Y-m-d'));$csrf=csrf_token();?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LSZJ Tagesabschluss</title><link rel="stylesheet" href="app.css"><style>.lamp{border-left:8px solid;padding:14px}.red{border-color:#c62828;background:#fff1f1}.yellow{border-color:#d69200;background:#fff8e1}.green{border-color:#24813b;background:#eefaf1}.incident{border:2px solid #c62828;padding:12px;margin:10px 0;border-radius:8px}.actions{display:flex;gap:8px;flex-wrap:wrap}.muted{color:#667085}</style></head><body><div class="nav"><a href="dashboard.php">Dashboard</a><a href="flight_approvals.php">Flugfreigaben</a><a href="duty_officer.php">Flugdienstleiter</a></div><h1>Tagesabschluss</h1><div class="card"><label>Betriebstag <input id="date" type="date" value="<?=htmlspecialchars($date,ENT_QUOTES,'UTF-8')?>"></label> <button onclick="loadStatus()">Prüfen</button></div><div id="state"></div><div id="red"></div><div id="yellow"></div><div id="green"></div><div id="manage" class="card"></div><script>const csrf=<?=json_encode($csrf)?>;const q=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function call(url,data){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,csrf_token:csrf})});let j=await r.json();if(!j.ok)alert(j.error||'Fehler');return j}async function loadStatus(){history.replaceState(null,'','?date='+encodeURIComponent(q('date').value));let d=await(await fetch('api_flight_day_status.php?date='+encodeURIComponent(q('date').value)+'&_='+Date.now())).json();if(!d.ok){alert(d.error);return}q('state').innerHTML='<div class="card"><b>Status:</b> '+(d.state.status==='closed'?'Abgeschlossen':'Offen')+(d.state.closed_at?' seit '+esc(d.state.closed_at):'')+'</div>';q('red').innerHTML=d.red.length?'<div class="lamp red"><h2>Rot: Sicherheitsprüfung erforderlich</h2>'+d.red.map(x=>`<div class="incident"><b>${esc(x.callsign||'Operation '+x.operation_id)}</b><br>Pilot: ${esc(x.pilot||'nicht erfasst')}<br>Start: ${esc(x.departure_time||'')}<br>${esc(x.message)}<div class="actions">${x.ktrax_url?`<a class="button warn" target="_blank" rel="noopener noreferrer" href="${x.ktrax_url}">In KTrax Tracking öffnen</a>`:''}<button onclick="navigator.clipboard.writeText('${esc(x.callsign||'')}')">Rufzeichen kopieren</button><a class="button" href="flight_correction.php?operation_id=${x.operation_id}">Flug bearbeiten</a></div></div>`).join('')+'</div>':'';q('yellow').innerHTML=d.yellow.length?'<div class="lamp yellow"><h2>Gelb: Offene Arbeiten</h2>'+d.yellow.map(x=>`<p><a href="flight_approvals.php?from=${d.date}&to=${d.date}&status=all#op-${x.operation_id}">Operation ${x.operation_id}, ${esc(x.callsign)}</a>: ${esc(x.message)}${x.fields?.length?' - '+x.fields.map(esc).join(', '):''}</p>`).join('')+'</div>':'';q('green').innerHTML=d.green?'<div class="lamp green"><h2>Grün: Betriebstag ist abschlussbereit</h2></div>':'';if(d.state.status==='closed')q('manage').innerHTML='<h2>Tag wieder öffnen</h2><label>Begründung (Pflicht)<textarea id="reason" required></textarea></label><button onclick="reopenDay()">Wieder öffnen</button>';else q('manage').innerHTML='<h2>Betriebstag abschliessen</h2><label>Bemerkung<textarea id="note"></textarea></label><button '+(d.green?'':'disabled')+' onclick="closeDay()">Betriebstag abschliessen</button>'}async function closeDay(){if(confirm('Betriebstag verbindlich abschliessen?')){let j=await call('api_close_flight_day.php',{date:q('date').value,note:q('note').value});if(j.ok)loadStatus()}}async function reopenDay(){let reason=q('reason').value.trim();if(!reason){alert('Begründung ist erforderlich.');return}let j=await call('api_reopen_flight_day.php',{date:q('date').value,reason});if(j.ok)loadStatus()}loadStatus();</script></body></html>